// cocking ring's teeth, its downward lug picks up the cam's tab on the setting stroke.
// involute spur outline: base circle rb = rp·cos 20°; a flank point at radius r lies at polar angle
// θ(r) = π/(2z) + inv(20°) − inv(acos(rb/r)) from the tooth's centre line, inv(α) = tan α − α
  function involute(m, z, c, a0 = 0, from = null, to = null, hub = null) {
    const alpha = 20 * Math.PI / 180, rp = m * z / 2, rb = rp * Math.cos(alpha), ra = rp + m, rf = rp - 1.25 * m
    const inv = a => Math.tan(a) - a, half = Math.PI / (2 * z) + inv(alpha), out = []
    const P = (r, a) => [c[0] + r * Math.cos(a), c[1] + r * Math.sin(a)]
    const flank = []; for (let i = 0; i <= 5; i++) { const r = Math.max(rb, rf) + (ra - Math.max(rb, rf)) * i / 5; flank.push([r, half - inv(Math.acos(Math.min(1, rb / r)))]) }
    const step = 2 * Math.PI / z
    // teeth in angular order: all of them, or those whose centre lies between from and to (degrees, counter-clockwise)
    const centres = []
    if (from === null) for (let k = 0; k < z; k++) centres.push(a0 * Math.PI / 180 + k * step)
    else { const span = ((((to - from) % 360) + 360) % 360) * Math.PI / 180, f0 = from * Math.PI / 180, base = a0 * Math.PI / 180
      let k = Math.ceil((f0 - base) / step); for (let ac = base + k * step; ac <= f0 + span + 1e-9; ac = base + (++k) * step) centres.push(ac) }
    for (const ac of centres) {
      out.push(P(rf, ac - step / 2 + 0.0001))
      if (rf < rb) out.push(P(rf, ac - flank[0][1]))
      for (const [r, th] of flank) out.push(P(r, ac - th))
      for (const [r, th] of flank.slice().reverse()) out.push(P(r, ac + th))
      if (rf < rb) out.push(P(rf, ac + flank[0][1]))
    }
    return out
  }
