const P_speedCam = (() => {
// Speed cam (cam ring) 552 [M p. 3, L Figs 24, 31–37]: on the lens flange; its steps set the segment's wait, hold the
// pallet out from 1/30 and hold the retard lever off at 1/500. (The model reads the steps as stops; drawn as the ring.)
  const P = { bore: 31.8, od: 52.8 }
  return j.part('Speed cam 552').color('#8e959c')  // material: steel
    .material(steel)
    .extrude(j.region.circle(P.od / 2).subtract(j.region.circle(P.bore / 2)).subtract(j.region.circle(4.2, { at: [15.8704, 14.7994] })).subtract(j.region.circle(3.2, { at: [19.3306, 8.2054] })).on(j.plane.offset(j.plane.XY, mm(16.2))), mm(0.5), { id: 'cam' })
})()
const P_speedRing = (() => {
// Speed setting ring [L Fig. 26]: knurled, Ø58.5 [S]; engraved B 1 2 4 8 15 30 60 125 250 500.
  const P = { od: 58.5, bore: 33.6 }
  return j.part('Speed setting ring').color('#d9dcdf')  // material: aluminium
    .material(aluminium)
    .extrude(j.region.circle(P.od / 2).subtract(j.region.circle(P.od / 2 - 2.2)).on(j.plane.offset(j.plane.XY, mm(17.2))), mm(1.4), { id: 'ring' })
})()
const P_cover = (() => {
// Front cover plate with the retaining ring 547 [M p. 1, L Fig. 23].
  return j.part('Front cover plate').color('#2c2d30')  // material: aluminium
    .material(aluminium).finish({ finish: 'anodized-black' })  // black anodized
    .extrude(j.region.circle(28.25).subtract(j.region.circle(16)).on(j.plane.offset(j.plane.XY, mm(18.6))), mm(0.6), { id: 'cover' })
    .extrude(j.region.circle(17.4).subtract(j.region.circle(15.8)).on(j.plane.offset(j.plane.XY, mm(19.2))), mm(0.8), { id: 'retainingRing' })
})()
const P_iris = (() => {
// Diaphragm [L p. 20]: the leaf stack, drawn at full aperture Ø24 [G], its plane 10.2 behind the front.
  return j.part('Diaphragm').color('#202124')  // material: steel
    .material(steel).finish({ finish: 'black-oxide' })  // blackened steel
    .extrude(j.region.circle(27.45).subtract(j.region.circle(12)).on(j.plane.offset(j.plane.XY, mm(9.2))), mm(0.6), { id: 'leaves' })
})()
return j.assembly('Synchro-Compur 0-MXV')
